function count_trailing_zeros_or_ones(val_64bit):
  bit0 = val_64bit & 1
  count = 0
  for i = 0 to 63:
    if ((val_64bit >> i) & 1) == bit0:
      count = count + 1
    else:
      break
  if count > 63:
    count = 63
  return count

function count_leading_zeros_or_ones(val_64bit):
  bit63 = (val_64bit >> 63) & 1
  count = 0
  for i = 63 down to 0:
    if ((val_64bit >> i) & 1) == bit63:
      count = count + 1
    else:
      break
  if count > 63:
    count = 63
  return count

function generate_digest(reg_type, val_64bit):
  if reg_type == INT:
    trailing_count = count_trailing_zeros_or_ones(val_64bit) & 0x3F
    leading_count = count_leading_zeros_or_ones(val_64bit) & 0x3F
    lsb6 = val_64bit & 0x3F
    digest = (trailing_count) ^ (leading_count << 3) ^ (lsb6 << 6)
    return digest & 0x0FFF
  else if reg_type == FP:
    // Inspect MSBs to classify FP format
    if is_fp16(val_64bit):
      // Val[15:13] placed at digest[5:3]
      fp16_val = ((val_64bit >> 13) & 0x7) << 3
      return fp16_val
    else if is_fp32(val_64bit):
      // Val[31:26] placed at digest[8:3]
      fp32_val = ((val_64bit >> 26) & 0x3F) << 3
      return fp32_val
    else: // FP64
      // Val[63:55] placed at digest[11:3]
      fp64_val = ((val_64bit >> 55) & 0x1FF) << 3
      return fp64_val
  else if reg_type == FLAG:
    // Replicate 4 condition flags 3 times into 12 bits
    flags = val_64bit & 0xF
    flag_val = (flags << 8) | (flags << 4) | flags
    return flag_val
  return 0
